/**
 * Regenerates docs/ui-memory/generated/* from source so the shared memory
 * cannot drift from the code.
 *
 *   npm run memory:sync    rewrite the generated files
 *   npm run memory:check   exit 1 if they are out of date (used in CI)
 *
 * Runs on Node's built-in TypeScript type stripping (Node >= 22.18).
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src");
const outDir = join(root, "docs", "ui-memory", "generated");
const HEADER = "<!-- Generated by `npm run memory:sync`. Do not edit by hand. -->\n\n";

function walk(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

const rel = (path: string) => relative(root, path).split("\\").join("/");
const isComponentFile = (path: string) => /\.(tsx|jsx)$/.test(path) && !/\.test\.|\.spec\./.test(path);

function exportedComponents(path: string): string[] {
  const code = readFileSync(path, "utf8");
  const names = [...code.matchAll(/export\s+(?:default\s+)?function\s+([A-Z]\w*)/g)].map((m) => m[1] ?? "");
  const consts = [...code.matchAll(/export\s+const\s+([A-Z]\w*)\s*=/g)].map((m) => m[1] ?? "");
  return [...new Set([...names, ...consts])].filter(Boolean);
}

function componentsDoc(): string {
  const groups: Array<[title: string, note: string, dirs: string[]]> = [
    ["Design system", "`src/shared/ui`: reuse these before writing new markup.", ["shared/ui"]],
    ["Layout", "`src/shared/layout`: app shell, navigation, page headers.", ["shared/layout"]],
    ["Shared components", "`src/shared/components`: cross-feature composites.", ["shared/components"]],
    ["Features", "`src/features/<role>/<feature>`.", ["features"]],
    ["App", "`src/app`: providers and router.", ["app"]],
    ["Legacy (being replaced)", "Pre-revamp code. Do not extend; rebuild under `features/` or `shared/`.", ["components", "roles", "App.jsx"]],
  ];
  let out = `${HEADER}# Component inventory\n`;
  for (const [title, note, dirs] of groups) {
    const files = dirs
      .flatMap((dir) => {
        const path = join(src, dir);
        return existsSync(path) && statSync(path).isFile() ? [path] : walk(path);
      })
      .filter(isComponentFile)
      .sort();
    const rows = files.map((file) => [rel(file), exportedComponents(file)] as const).filter(([, names]) => names.length);
    out += `\n## ${title}\n\n${note}\n\n`;
    out += rows.length
      ? `| File | Exports |\n| --- | --- |\n${rows.map(([file, names]) => `| \`${file}\` | ${names.map((n) => `\`${n}\``).join(", ")} |`).join("\n")}\n`
      : "_None yet._\n";
  }
  return out;
}

function routesDoc(): string {
  const routerFiles = walk(join(src, "app", "router")).filter((f) => /\.tsx?$/.test(f) && !/\.test\./.test(f));
  const routes = routerFiles.flatMap((file) =>
    [...readFileSync(file, "utf8").matchAll(/<Route\s+[^>]*path="([^"]+)"[^>]*element=\{<(\w+)/g)].map((m) => [m[1], m[2], rel(file)] as const),
  );
  const roles = readFileSync(join(src, "roles", "shared", "roleRouter.js"), "utf8").match(/VALID_ROLES\s*=\s*\[([^\]]+)\]/)?.[1] ?? "";
  let out = `${HEADER}# Routes\n\n## Roles\n\n${roles.split(",").map((r) => `- \`/${r.trim().replace(/"/g, "")}\``).join("\n")}\n`;
  out += "\nEach role also resolves from `?role=<role>`, `#/<role>`, `/<role>.html`, and `/<role>/index.html` (see `e2e/routing.spec.ts`).\n";
  out += `\n## Route table\n\n| Path | Element | Defined in |\n| --- | --- | --- |\n${routes.map(([p, e, f]) => `| \`${p}\` | \`${e}\` | \`${f}\` |`).join("\n")}\n`;
  return out;
}

function tokensDoc(): string {
  const css = readFileSync(join(src, "shared", "styles", "tailwind.css"), "utf8");
  const theme = css.slice(css.indexOf("@theme"));
  const tokens = [...theme.matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)]
    .map((m) => [m[1] ?? "", (m[2] ?? "").trim()] as const)
    .filter(([name]) => !name.includes("--"));
  const groups: Array<[title: string, prefix: string, usage: string]> = [
    ["Colors", "color-", "`text-<name>`, `bg-<name>`, `border-<name>`"],
    ["Type scale", "text-", "`text-<name>` (body minimum is `text-body`, 14px)"],
    ["Radius", "radius-", "`rounded-<name>`"],
    ["Shadow", "shadow-", "`shadow-<name>`"],
    ["Spacing", "spacing-", "`min-h-<name>`, `size-<name>`, …"],
    ["Font", "font-", "`font-<name>`"],
  ];
  let out = `${HEADER}# Design tokens\n\nSource: \`src/shared/styles/tailwind.css\`. Contrast is enforced by \`tokens.test.ts\`.\n`;
  for (const [title, prefix, usage] of groups) {
    const rows = tokens.filter(([name]) => name.startsWith(prefix));
    if (!rows.length) continue;
    out += `\n## ${title}\n\nUse as ${usage}.\n\n| Token | Value |\n| --- | --- |\n`;
    out += rows.map(([name, value]) => `| \`${name.slice(prefix.length)}\` | \`${value === "initial" ? "removed" : value}\` |`).join("\n") + "\n";
  }
  return out;
}

const files: Record<string, string> = {
  "components.md": componentsDoc(),
  "routes.md": routesDoc(),
  "tokens.md": tokensDoc(),
};

const check = process.argv.includes("--check");
const stale: string[] = [];
mkdirSync(outDir, { recursive: true });
for (const [name, content] of Object.entries(files)) {
  const path = join(outDir, name);
  const current = existsSync(path) ? readFileSync(path, "utf8") : "";
  if (current === content) continue;
  if (check) stale.push(rel(path));
  else writeFileSync(path, content);
}

if (check && stale.length) {
  console.error(`UI memory is out of date: ${stale.join(", ")}\nRun \`npm run memory:sync\` and commit the result.`);
  process.exit(1);
}
console.log(check ? "UI memory is up to date." : `Wrote ${Object.keys(files).length} files to ${rel(outDir)}`);
